mapper.select:
select ia.id as id, ia.company_id as companyId, ia.customer_id as customerId, it.company_name as saleCompanyName, it.tax_number as saleTaxNumber, it.bank_name as saleBankName, it.bank_account as saleBankAccount, it.telephone as saleTelephone, it.address as saleAddress, ia.buyer_company_name as buyerCompanyName, ia.buyer_tax_number as buyerTaxNumber, ia.buyer_bank_name as buyerBankName, ia.buyer_bank_account as buyerBankAccount, ia.buyer_telephone as buyerTelephone, ia.buyer_address as buyerAddress, ia.buyer_type as buyerType, ia.invoice_type as invoiceType, ia.is_architecture as isArchitecture, ia.is_trans_province as isTransProvince, ia.product_location as productLocation, ia.invoice_title_id as invoiceTitleId, ia.status as status, ia.invoice_url as invoiceUrl, ia.remark as remark, ia.create_time as createTime from invoice_apply ia left join invoice_title it on ia.invoice_title_id = it.id where ia.deleted = 0
and ia.company_id = #{params.companyId}
and ia.buyer_company_name like concat('%', #{params.buyerCompanyName}, '%')
AND DATE_FORMAT(ia.create_time, '%Y-%m-%d') >= #{params.startDate}
AND DATE_FORMAT(ia.create_time, '%Y-%m-%d') <= #{params.endDate}
order by createTime desc

select ia.id as id, cc.company_name as companyName, ci.customer_name as customerName, it.company_name as saleCompanyName, it.tax_number as saleTaxNumber, it.bank_name as saleBankName, it.bank_account as saleBankAccount, it.telephone as saleTelephone, it.address as saleAddress, ia.buyer_company_name as buyerCompanyName, ia.buyer_tax_number as buyerTaxNumber, ia.buyer_bank_name as buyerBankName, ia.buyer_bank_account as buyerBankAccount, ia.buyer_telephone as buyerTelephone, ia.buyer_address as buyerAddress, ia.buyer_type as buyerType, ia.invoice_type as invoiceType, ia.is_architecture as isArchitecture, ia.is_trans_province as isTransProvince, ia.product_location as productLocation, ia.invoice_title_id as invoiceTitleId, ia.status as status, ia.invoice_url as invoiceUrl, ia.remark as remark, ia.create_time as createTime from invoice_apply ia left join invoice_title it on ia.invoice_title_id = it.id left join customer_company cc on ia.company_id = cc.id left join customer_info ci on ia.customer_id = ci.id where ia.deleted = 0
and cc.company_name like concat('%', #{params.companyName}, '%')
and ci.customer_name like concat('%', #{params.customerName}, '%')
and ia.status = #{params.status}
and ia.buyer_company_name like concat('%', #{params.buyerCompanyName}, '%')
AND DATE_FORMAT(ia.create_time, '%Y-%m-%d') >= #{params.startDate}
AND DATE_FORMAT(ia.create_time, '%Y-%m-%d') <= #{params.endDate}
and (ci.create_by in
#{item}
or ci.owner_user in
#{item}
)
order by createTime desc
